import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"Page layout","description":"How a page appears in the Portal — width, cover, colors, and navigation.","frontmatter":{"title":"Page layout","description":"How a page appears in the Portal — width, cover, colors, and navigation."},"headers":[],"relativePath":"en/seiten/seitenlayout.md","filePath":"en/seiten/seitenlayout.md","lastUpdated":1787319236000}'),i={name:"en/seiten/seitenlayout.md"};function s(r,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="page-layout" tabindex="-1">Page layout <a class="header-anchor" href="#page-layout" aria-label="Permalink to &quot;Page layout&quot;">​</a></h1><p>The page settings determine how a page looks as a <a href="/en/seiten/portal-veroeffentlichen">Portal</a>. You reach them via the page menu (<em>Open page menu</em>).</p><div class="warning custom-block"><p class="custom-block-title">These settings apply in the Portal, not the editor</p><p>The page layout carries the note <em>Applies to the Portal display</em>. In the editor, you continue to see the editing view.</p><p>Check the result via <strong>Preview</strong> — either as <em>Smartphone</em> or <em>Desktop</em>.</p></div><h2 id="setting-the-page-layout" tabindex="-1">Setting the page layout <a class="header-anchor" href="#setting-the-page-layout" aria-label="Permalink to &quot;Setting the page layout&quot;">​</a></h2><p>Three options:</p><table tabindex="0"><thead><tr><th>Layout</th><th>Appearance</th></tr></thead><tbody><tr><td><strong>Centered page</strong></td><td>Content at a limited width, centered</td></tr><tr><td><strong>Full width</strong></td><td>Content uses the whole window width</td></tr><tr><td><strong>Card view</strong></td><td>Content shown as a raised card</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Which one for what</p><ul><li><strong>Centered page</strong> for text-heavy content — documentation, manuals, explainer pages. A limited line length reads better.</li><li><strong>Full width</strong> for dashboards and embedded tables. A <a href="/en/seiten/auswertungen">Grid view</a> needs room.</li><li><strong>Card view</strong> for short, self-contained pages — sign-ups, feedback forms, single forms.</li></ul></div><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><p>In the <strong>Page</strong> section:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Set icon &amp; color</strong></td><td>Symbol and color in the navigation</td></tr><tr><td><strong>Add cover image</strong></td><td>Image above the page content</td></tr><tr><td><strong>Set background color</strong></td><td>Background of the page</td></tr></tbody></table><p>If a cover is already set, the action is called <strong>Edit cover image</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Use a cover image thoughtfully</p><p>A cover image pushes the actual content further down. On mobile, that can mean visitors have to scroll before seeing anything useful.</p><p>For Portals with a clear task — fill out a form, check a status — less is often more.</p></div><h2 id="collapsible-navigation" tabindex="-1">Collapsible navigation <a class="header-anchor" href="#collapsible-navigation" aria-label="Permalink to &quot;Collapsible navigation&quot;">​</a></h2><p>For pages with <strong>sub-pages</strong>, <strong>Collapsible navigation</strong> controls whether visitors can collapse the navigation.</p><div class="tip custom-block"><p class="custom-block-title">Turn it on with many sub-pages</p><p>On narrow screens, an expanded navigation takes up half the space. Making it collapsible makes the Portal significantly more usable there.</p></div><h2 id="editing-and-access" tabindex="-1">Editing and access <a class="header-anchor" href="#editing-and-access" aria-label="Permalink to &quot;Editing and access&quot;">​</a></h2><p>In the <strong>Editing &amp; access</strong> section:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description in the interface</th></tr></thead><tbody><tr><td><strong>Lock page</strong></td><td><em>Blocks can no longer be edited</em></td></tr><tr><td><strong>Confirm correct account</strong></td><td><em>Users confirm their identity before continuing.</em></td></tr><tr><td><strong>Auto-submit on load</strong></td><td><em>Submits this page automatically when it loads.</em></td></tr></tbody></table><h3 id="lock-page" tabindex="-1">Lock page <a class="header-anchor" href="#lock-page" aria-label="Permalink to &quot;Lock page&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Recommended for live pages</p><p>Once a page is in use, locking it prevents someone from accidentally moving a block or overwriting text while viewing it. You can unlock it again at any time.</p></div><h3 id="confirm-correct-account" tabindex="-1">Confirm correct account <a class="header-anchor" href="#confirm-correct-account" aria-label="Permalink to &quot;Confirm correct account&quot;">​</a></h3><p>Shows a notice with which account the person is signed in as, along with the option to confirm or switch.</p><div class="tip custom-block"><p class="custom-block-title">On shared devices</p><p>Useful anywhere multiple people share the same device — a workshop, a reception desk, a training room. It prevents someone from submitting under someone else&#39;s name.</p></div><h3 id="auto-submit-on-load" tabindex="-1">Auto-submit on load <a class="header-anchor" href="#auto-submit-on-load" aria-label="Permalink to &quot;Auto-submit on load&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Needs fully prefilled values</p><p>If the page submits itself on load, no one gets the chance to fill in fields. All required values must be set via the link.</p><p>The typical use is a QR code whose scan immediately starts a <a href="/en/flows/was-ist-ein-flow">Flow</a> — an attendance check-in or a material request, for example.</p></div><h2 id="usage-in-flows" tabindex="-1">Usage in Flows <a class="header-anchor" href="#usage-in-flows" aria-label="Permalink to &quot;Usage in Flows&quot;">​</a></h2><p>The <strong>Usage in Flows</strong> section shows which Flows display this page.</p><div class="warning custom-block"><p class="custom-block-title">Check before deleting</p><p>If a Flow step uses the page, that Flow will subsequently fail with the error <em>No dedicated UI is assigned to this step</em>.</p><p>→ <a href="/en/flows/seiten-in-flows">Pages in Flows</a></p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/seiten/portal-veroeffentlichen">Publishing a Portal</a></li><li><a href="/en/seiten/portal-einbetten">Embedding a Portal</a></li><li><a href="/en/seiten/seite-erstellen">Creating and editing a page</a></li></ul>',30)])])}const u=t(i,[["render",s]]);export{g as __pageData,u as default};
